function updateConversion(){
  const amountRaw = $('amount').value.trim();
  const rateRaw = $('rate').value.trim();
  const amountValue = Number(amountRaw);
  const rate = Number(rateRaw);
  const to = $('to-currency').value;
  const validAmount = amountRaw !== '' && Number.isFinite(amountValue) && amountValue >= 0 && amountValue <= 1_000_000_000;
  const validRate = rateRaw !== '' && Number.isFinite(rate) && rate > 0 && rate <= 1_000_000_000;
  const result = amountValue * rate;
  if (!validAmount || !validRate || !Number.isFinite(result) || result > 1e15) {
    $('converted').textContent = '—';
    $('rate-note').textContent = 'Enter a valid non-negative amount (up to 1 billion) and a positive rate (up to 1 billion).';
    return;
  }
  $('converted').textContent = money(result,to);
  $('rate-note').textContent = `1 ${$('from-currency').value} = ${rate} ${to} · ${$('rate').dataset.source || 'Manual rate; verify before use'}`;
}
['amount','rate','from-currency','to-currency'].forEach(id=>$(id).addEventListener('input',updateConversion));

const fetchRateButton = $('fetch-rate');
if (fetchRateButton) {
  fetchRateButton.addEventListener('click', async () => {
    const base = $('from-currency').value;
    const quote = $('to-currency').value;
    const oldText = fetchRateButton.textContent;
    fetchRateButton.disabled = true;
    fetchRateButton.textContent = 'Fetching…';
    try {
      const response = await fetch(`/api/rate?base=${encodeURIComponent(base)}&quote=${encodeURIComponent(quote)}`);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Rate unavailable');
      if (!Number.isFinite(Number(data.rate)) || Number(data.rate) <= 0) throw new Error('The service returned an invalid rate.');
      $('rate').value = Number(data.rate).toPrecision(8);
      $('rate').dataset.source = data.date ? `Reference rate ${data.date}; provider fees may differ` : data.source;
      updateConversion();
    } catch (error) {
      $('rate-note').textContent = error.message || 'Live rate unavailable; enter a rate manually.';
    } finally {
      fetchRateButton.disabled = false;
      fetchRateButton.textContent = oldText;
    }
  });
}

$('swap-currencies').addEventListener('click',()=>{
  const from=$('from-currency'), to=$('to-currency');
  const oldFrom=from.value, oldTo=to.value, oldRate=Math.max(0,Number($('rate').value)||0);
  from.value=oldTo; to.value=oldFrom;
  $('rate').value=oldRate>0 && Number.isFinite(1/oldRate)?(1/oldRate).toPrecision(8):'';
  updateConversion();
});

