// Explicit task-completion workflows. These endpoints perform calculations or
// write demo-only evidence; none of them initiate a real financial transaction.
async function postJSON(url, payload) {
  const response = await fetch(url, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(payload)
  });
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Request failed');
  return result;
}

function showWorkflowResult(id, value) {
  const target = $(id);
  if (!target) return;

  if (typeof value === 'string') {
    target.textContent = value;
    return;
  }

  const money = (amount, currency) =>
    `${currency || ''} ${Number(amount || 0).toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    })}`;

  if (id === 'agent-plan-result' && value.calculation) {
    const c = value.calculation;
    const i = value.inputs || {};
    target.textContent =
      `Budget plan: ${value.status || 'calculated'}\n\n` +
      `Available funds: ${money(i.available_funds, value.currency)}\n` +
      `Total planned costs: ${money(c.total_planned_costs, value.currency)}\n` +
      `Remaining balance: ${money(c.remaining_after_confirmed_funding, value.currency)}\n` +
      `Funding gap: ${money(c.funding_gap, value.currency)}\n\n` +
      `${value.rule || ''}\n${value.period_note || ''}`;
    return;
  }

  if (id === 'transfer-result' &&
      value.estimated_recipient_amount !== undefined) {
    target.textContent =
      `Estimated amount received\n\n` +
      `${money(value.estimated_recipient_amount, value.quote)}\n\n` +
      `Amount sent: ${money(value.amount, value.base)}\n` +
      `Transfer fee: ${money(value.fee, value.base)}\n` +
      `Exchange rate: ${value.rate}\n\n` +
      `${value.disclaimer || 'Illustrative estimate based on the values entered.'}`;
    return;
  }

  target.textContent = JSON.stringify(value, null, 2);
}

