// Five-module dashboard interactions: local-only mood check-in, reminders and CGPA ratio.
(function () {
  const byId = id => document.getElementById(id);
  const eventTitle = byId('event-title'), eventDate = byId('event-date'), eventList = byId('event-list');
  let reminders = [];
  function renderReminders() {
    if (!eventList) return;
    if (!reminders.length) { eventList.innerHTML = '<p class="empty-note">Your reminders will appear here. They stay in this page session.</p>'; return; }
    eventList.innerHTML = reminders.map((item, i) => `<div class="local-list-item"><span>${escapeHTML(item.title)}<small>${escapeHTML(item.date || 'Date not set')}</small></span><button type="button" data-remove-reminder="${i}" aria-label="Remove reminder">Remove</button></div>`).join('');
  }
  function escapeHTML(value) { return String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch])); }
  byId('add-event')?.addEventListener('click', () => {
    const title = eventTitle?.value.trim();
    if (!title) { eventTitle?.focus(); return; }
    reminders.push({title, date:eventDate?.value || ''});
    reminders.sort((a,b) => (a.date || '9999').localeCompare(b.date || '9999'));
    if (eventTitle) eventTitle.value = '';
    renderReminders();
  });
  eventList?.addEventListener('click', e => { const b=e.target.closest('[data-remove-reminder]'); if (b) { reminders.splice(Number(b.dataset.removeReminder),1); renderReminders(); } });

  const moodCopy = {
    great:'Love that for you. If you have the energy, enjoy it without needing to make the day more productive.',
    okay:'Okay is a valid place to be. Pick one manageable task, then give yourself permission to pause.',
    low:'I’m sorry it feels low today. Try a gentle reset, and consider messaging someone you trust rather than handling everything alone.',
    stressed:'Let’s make the next step smaller: take a few slow breaths, write down the one most urgent thing, and leave the rest for later.'
  };
  document.querySelectorAll('[data-mood]').forEach(button => button.addEventListener('click', () => {
    document.querySelectorAll('[data-mood]').forEach(b => { b.classList.remove('active'); b.setAttribute('aria-pressed','false'); });
    button.classList.add('active'); button.setAttribute('aria-pressed','true');
    const response = byId('mood-response'); if (response) response.textContent = moodCopy[button.dataset.mood] || 'Take a gentle pause and do what feels manageable.';
  }));

  byId('calculate-cgpa')?.addEventListener('click', () => {
    const value = Number(byId('cgpa-value')?.value), scale = Number(byId('cgpa-scale')?.value || 4), result = byId('cgpa-result');
    if (!Number.isFinite(value) || value < 0 || value > scale) { if (result) result.textContent = `Enter a CGPA between 0 and ${scale}.`; return; }
    if (result) result.textContent = `${(value / scale * 100).toFixed(1)}% of the selected ${scale.toFixed(2)}-point scale. This is a simple ratio, not an official GPA conversion or reward eligibility result.`;
  });

  function updateSpendingHealth() {
    const income = Number(byId('income')?.value || 0);
    const ids = ['tuition','housing','food','transport','other'];
    const expenses = ids.reduce((sum,id) => sum + Number(byId(id)?.value || 0),0);
    const value = byId('spending-health-value'), fill = byId('spending-health-fill'), message = byId('spending-health-message');
    if (!value || !fill || !message) return;
    if (income <= 0) { value.textContent='Add income'; fill.style.width='0%'; message.textContent='Enter a positive monthly income in Wallet & Cards to calculate this indicator.'; return; }
    const ratio = expenses / income * 100;
    value.textContent = `${Math.round(ratio)}% planned`;
    fill.style.width = `${Math.min(100,Math.max(0,ratio))}%`;
    if (ratio > 100) message.textContent = `Overspending warning: planned costs exceed available funds by ${(expenses-income).toLocaleString()}. Recheck the amounts and timing.`;
    else if (ratio >= 85) message.textContent = 'Your plan has a narrow buffer. Consider checking upcoming one-time costs before committing to extra spending.';
    else message.textContent = 'Your entered costs are below your available funds. Keep a buffer for unexpected costs; this is only an estimate from your inputs.';
  }
  ['income','tuition','housing','food','transport','other','currency'].forEach(id => { byId(id)?.addEventListener('input',updateSpendingHealth); byId(id)?.addEventListener('change',updateSpendingHealth); });
  updateSpendingHealth();
})();


// Study-abroad planning tools integrated with the existing Nexora dashboard.
(() => {
  const el = id => document.getElementById(id);
  const number = id => {
    const value = Number(el(id)?.value ?? 0);
    return Number.isFinite(value) && value >= 0 ? value : 0;
  };
  const fmt = (value, currency) => {
    try { return new Intl.NumberFormat(undefined, {style:'currency', currency, maximumFractionDigits:2}).format(value); }
    catch { return `${value.toLocaleString(undefined,{maximumFractionDigits:2})} ${currency}`; }
  };
  let latestStudyPlan = null;

  el('study-cost-form')?.addEventListener('submit', event => {
    event.preventDefault();
    const currency = el('study-currency').value;
    const years = Math.min(10, Math.max(.5, Number(el('study-years').value) || 1));
    const tuition = number('study-tuition');
    const living = number('study-living');
    const scholarship = Math.min(tuition, number('study-scholarship'));
    const insurance = number('study-insurance');
    const other = number('study-other');
    const inflation = Math.min(30, number('study-inflation')) / 100;
    const risk = Math.min(30, number('study-fx-risk')) / 100;
    const oneTime = number('study-visa') + number('study-flight');
    const recurring = tuition - scholarship + living + insurance + other;
    let recurringTotal = 0;
    for (let year = 1; year <= Math.ceil(years); year++) {
      const fraction = Math.min(1, years - (year - 1));
      recurringTotal += recurring * Math.pow(1 + inflation, year - 1) * fraction;
    }
    const base = recurringTotal + oneTime;
    const total = base * (1 + risk);
    const scholarshipTotal = scholarship * years;
    latestStudyPlan = {country:el('study-country').value.trim(),city:el('study-city').value.trim(),currency,years,tuition,living,scholarship,insurance,other,inflation_percent:inflation*100,risk_percent:risk*100,base_total:base,risk_adjusted_total:total,scholarship_reduction:scholarshipTotal,one_time_cost:oneTime};
    el('study-total').textContent = fmt(total,currency);
    el('study-base-total').textContent = fmt(base,currency);
    el('study-risk-amount').textContent = fmt(total-base,currency);
    el('study-scholarship-total').textContent = fmt(scholarshipTotal,currency);
    el('study-one-time').textContent = fmt(oneTime,currency);
    const destination = [latestStudyPlan.city,latestStudyPlan.country].filter(Boolean).join(', ');
    el('study-destination-label').textContent = `${destination || 'Your destination'} · ${years} year${years===1?'':'s'} · ${currency}`;
    el('study-plan-note').textContent = 'Estimate only. The total applies your entered inflation and currency-risk buffer; it does not verify tuition, scholarships, visa costs or exchange rates.';
  });

  el('study-reset')?.addEventListener('click', () => {
    el('study-cost-form')?.reset();
    latestStudyPlan = null;
    ['study-total','study-base-total','study-risk-amount','study-scholarship-total','study-one-time'].forEach(id => el(id).textContent='—');
    el('study-destination-label').textContent='Enter your destination and calculate your plan.';
  });

  el('study-export')?.addEventListener('click', () => {
    if (!latestStudyPlan) { el('study-plan-note').textContent='Calculate a plan before exporting it.'; return; }
    const rows = [['Field','Value'], ...Object.entries(latestStudyPlan)];
    const csv = rows.map(row => row.map(value => `"${String(value).replaceAll('"','""')}"`).join(',')).join('\r\n');
    const url = URL.createObjectURL(new Blob([csv], {type:'text/csv;charset=utf-8;'}));
    const a = document.createElement('a'); a.href=url; a.download='nexora-study-abroad-plan.csv'; a.click(); URL.revokeObjectURL(url);
  });

  el('run-study-comparison')?.addEventListener('click', () => {
    const opts = ['a','b'].map(key => {
      const country = el(`compare-${key}-country`).value.trim() || `Destination ${key.toUpperCase()}`;
      const currency = el(`compare-${key}-currency`).value;
      const tuition = number(`compare-${key}-tuition`);
      const living = number(`compare-${key}-living`);
      const scholarship = Math.min(tuition, number(`compare-${key}-scholarship`));
      return {country,currency,annual:tuition+living-scholarship,tuition,living,scholarship};
    });
    el('study-comparison-result').innerHTML = opts.map(o => `<div class="study-comparison-card"><span>${o.country.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}</span><strong>${fmt(o.annual,o.currency)}</strong><small>Annual estimate after entered scholarship · ${o.currency}</small></div>`).join('');
    const note = document.createElement('p');
    note.className = 'study-note';
    note.textContent = opts[0].currency === opts[1].currency ? 'Both estimates use the same currency, so the annual figures can be compared directly.' : 'Currencies differ. Do not compare the raw totals directly; convert both using a dated reference rate and verify actual provider fees.';
    el('study-comparison-result').appendChild(note);
  });

  el('study-savings-form')?.addEventListener('submit', event => {
    event.preventDefault();
    const target = number('goal-target');
    const saved = Math.min(target, number('goal-saved'));
    const months = Math.max(1, Math.min(120, Number(el('goal-months').value) || 1));
    const income = number('goal-income');
    const expenses = number('goal-expenses');
    const remaining = Math.max(0, target - saved);
    const monthly = remaining / months;
    const cashflow = income - expenses;
    el('goal-monthly-needed').textContent = fmt(monthly, 'USD');
    el('goal-remaining').textContent = fmt(remaining, 'USD');
    el('goal-cashflow').textContent = fmt(cashflow, 'USD');
    el('goal-status').textContent = cashflow < 0 ? 'Expenses exceed income' : monthly <= cashflow ? 'Within entered cash flow' : 'Target exceeds cash flow';
    el('goal-progress-fill').style.width = `${Math.min(100, target > 0 ? saved / target * 100 : 0)}%`;
    el('goal-advice').textContent = cashflow < 0
      ? 'Your entered monthly expenses exceed income. Recheck the figures before setting a savings commitment.'
      : monthly <= cashflow
        ? 'The target fits within the cash flow you entered, but keep room for emergencies and irregular costs.'
        : 'The monthly target is higher than your entered cash flow. Consider a longer timeline, more funding, or a revised cost estimate.';
  });
  el('study-savings-form')?.dispatchEvent(new Event('submit', {cancelable:true}));
})();


