function updateMegaHub() {
  const spend=Math.max(0,Number(document.getElementById('group-spend')?.value||0)), disc=Math.min(50,Math.max(0,Number(document.getElementById('group-discount')?.value||0)));
  const savings=spend*disc/100;
  const groupOut=document.getElementById('group-saving-result'); if(groupOut) groupOut.textContent=`Estimated monthly saving: $${savings.toFixed(2)} per student (${disc.toFixed(1)}% of $${spend.toFixed(2)}). Illustrative only; no group purchase is arranged.`;
  const target=Math.max(0,Number(document.getElementById('flight-target')?.value||0)), saved=Math.max(0,Number(document.getElementById('flight-saved')?.value||0));
  const flightOut=document.getElementById('flight-saving-result'); if(flightOut) flightOut.textContent=`Remaining target: $${Math.max(0,target-saved).toFixed(2)}. Suggested monthly saving over 6 months: $${(Math.max(0,target-saved)/6).toFixed(2)}. Nothing is locked or transferred.`;
}
['group-spend','group-discount','flight-target','flight-saved'].forEach(id=>document.getElementById(id)?.addEventListener('input',updateMegaHub));
updateMegaHub();
