// Human-in-the-loop agent workflow. This only records a sandbox simulation.
(function () {
  const $ = id => document.getElementById(id);
  let currentIntent = null;
  const prepare = $('prepare-agent-transfer');
  const confirm = $('confirm-agent-transfer');
  const consent = $('agent-transfer-confirm-check');
  if (!prepare || !confirm || !consent) return;
  const review = $('agent-transfer-review');
  const status = $('agent-transfer-status');
  function render(id, value) {
    const el = $(id);
    if (el) el.textContent = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
  }
  prepare.addEventListener('click', async () => {
    currentIntent = null;
    confirm.disabled = true;
    consent.checked = false;
    consent.disabled = true;
    render('agent-transfer-status', 'A preview is being prepared. No payment has been sent.');
    try {
      const data = await postJSON('/api/agent/transfer/prepare', {
        recipient_label: $('agent-recipient').value,
        amount: $('agent-transfer-amount').value,
        fee: $('agent-transfer-fee').value,
        rate: $('agent-transfer-rate').value,
        base: $('agent-transfer-base').value,
        quote: $('agent-transfer-quote').value
      });
      currentIntent = data.intent_id;
      render('agent-transfer-review', data);
      consent.disabled = false;
      render('agent-transfer-status', 'Review the details above. Tick the sandbox-only confirmation to enable the demo action.');
    } catch (error) {
      render('agent-transfer-review', error.message);
      render('agent-transfer-status', 'Could not prepare a preview. Check the values and try again.');
    }
  });
  consent.addEventListener('change', () => { confirm.disabled = !(currentIntent && consent.checked); });
  confirm.addEventListener('click', async () => {
    if (!currentIntent || !consent.checked) return;
    confirm.disabled = true;
    try {
      const data = await postJSON('/api/agent/transfer/confirm', {intent_id: currentIntent, confirm: true});
      render('agent-transfer-status', data);
      currentIntent = null;
      consent.checked = false;
      consent.disabled = true;
    } catch (error) {
      render('agent-transfer-status', error.message);
      confirm.disabled = false;
    }
  });
})();

// Compact persistent composer: expand on focus, keep expanded for conversation.
document.addEventListener('DOMContentLoaded', () => {
  const panel = document.querySelector('.chat-panel');
  const input = document.getElementById('chat-input');
  const toggle = document.getElementById('chat-toggle');
  if (!panel || !input) return;
  input.addEventListener('focus', () => panel.classList.add('chat-open'));
  if (toggle) toggle.addEventListener('click', () => {
    panel.classList.toggle('chat-open');
    if (panel.classList.contains('chat-open')) input.focus();
  });
  const form = document.getElementById('chat-form');
  if (form) form.addEventListener('submit', () => panel.classList.add('chat-open'));
});


// USD→BDT remittance comparison. Provider offers are entered by the user because
// personalized quotes are not reliably available through a free public API.
const remitFetch = $('remit-fetch-reference');
const remitReference = $('remit-reference');
const remitResults = $('remit-results');
if (remitFetch) {
  remitFetch.addEventListener('click', async () => {
    remitFetch.disabled = true;
    const prior = remitFetch.textContent;
    remitFetch.textContent = 'Fetching…';
    try {
      const response = await fetch('/api/rate?base=USD&quote=BDT');
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Reference rate unavailable.');
      const rate = Number(data.rate);
      if (!Number.isFinite(rate) || rate <= 0) throw new Error('Invalid reference rate returned.');
      const timestamp = new Date().toLocaleString();
      remitReference.textContent = `Reference only: 1 USD = ${rate.toLocaleString(undefined,{maximumFractionDigits:6})} BDT · Source: ${data.source || 'Frankfurter reference rate'}${data.date ? ` · Rate date: ${data.date}` : ''} · Retrieved: ${timestamp}. Provider fees and offered rates can differ.`;
      remitReference.dataset.rate = String(rate);
      remitReference.dataset.date = data.date || '';
    } catch (error) {
      remitReference.textContent = `${error.message || 'Reference rate unavailable.'} You can still compare manually entered provider offers.`;
    } finally {
      remitFetch.disabled = false;
      remitFetch.textContent = prior;
    }
  });
}
const remitCompare = $('remit-compare');
if (remitCompare) {
  remitCompare.addEventListener('click', async () => {
    const providers = [
      {name:'Remitly', key:'remitly'},
      {name:'Wise', key:'wise'},
      {name:'Western Union', key:'wu'}
    ].map(p => ({
      name:p.name,
      rate:$(`remit-${p.key}-rate`).value,
      fee:$(`remit-${p.key}-fee`).value,
      delivery:$(`remit-${p.key}-delivery`).value
    }));
    remitCompare.disabled = true;
    const prior = remitCompare.textContent;
    remitCompare.textContent = 'Comparing…';
    try {
      const response = await fetch('/api/remittance/compare', {
        method:'POST', headers:{'Content-Type':'application/json'},
        body:JSON.stringify({amount:$('remit-amount').value, providers})
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Could not compare offers.');
      if (!data.providers.length) {
        remitResults.textContent = 'No provider rows were available. Enter at least one offered exchange rate to calculate a recipient amount.';
        return;
      }
      remitResults.replaceChildren();
      const sorted = [...data.providers].sort((a,b) => {
        if (a.recipient_bdt == null) return 1;
        if (b.recipient_bdt == null) return -1;
        return b.recipient_bdt - a.recipient_bdt;
      });
      sorted.forEach(row => {
        const card = document.createElement('div');
        card.className = 'remit-result-card';
        const title = document.createElement('strong');
        title.textContent = row.provider;
        const amount = document.createElement('div');
        amount.className = 'remit-recipient';
        amount.textContent = row.recipient_bdt == null ? 'Recipient amount unavailable' : `${row.recipient_bdt.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})} BDT estimated`;
        const details = document.createElement('p');
        details.textContent = `Rate: ${row.offered_rate == null ? 'Not provided' : row.offered_rate} BDT/USD · Fee: ${row.fee_usd == null ? 'Not provided' : '$'+row.fee_usd.toFixed(2)} · Delivery: ${row.delivery_estimate} · ${row.quote_status}`;
        card.append(title, amount, details);
        remitResults.append(card);
      });
      const note = document.createElement('p');
      note.className = 'remit-disclaimer';
      note.textContent = `${data.formula}. Ranking uses the values you entered; offers missing a rate or fee have no recipient estimate. Quotes are not independently verified, and no transfer is executed.`;
      remitResults.append(note);
    } catch (error) {
      remitResults.textContent = error.message || 'Could not compare offers.';
    } finally {
      remitCompare.disabled = false;
      remitCompare.textContent = prior;
    }
  });
}


// Scholarship and university discovery: generates transparent targeted search links.
(function(){
 const $id=id=>document.getElementById(id);
 const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 async function search(kind){
  const university=kind==='university';
  const get=id=>($id(id)?.value||'').trim();
  const payload={kind,destination:get(university?'university-destination':'discovery-destination'),level:get(university?'university-level':'discovery-level'),subject:get(university?'university-subject':'discovery-subject'),nationality:university?'':get('discovery-nationality'),region:university?'':get('discovery-region')};
  const target=$id(university?'university-results':'scholarship-results');
  if(!payload.destination&&!payload.subject){target.textContent='Please enter at least a destination or subject to tailor your search.';return;}
  target.textContent='Preparing targeted official-source searches…';
  try{const r=await fetch('/api/discovery/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(data.error||'Search failed');
   target.innerHTML='<div class="discovery-links">'+data.results.map(x=>`<div class="local-list-item"><span><b>${esc(x.name)}</b><small>${esc(x.note)}</small></span><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Open ↗</a></div>`).join('')+'</div><p class="small-note">'+esc(data.notice)+'</p>';
  }catch(e){target.textContent='Could not prepare searches. Check that Nexora is running, then try again.';}
 }
 $id('find-scholarships')?.addEventListener('click',()=>search('scholarship'));
 $id('find-universities')?.addEventListener('click',()=>search('university'));
})();
